begin;
create extension if not exists vector with schema public;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text, created_at timestamptz not null default now());
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
create table public.modules(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,drive_id text not null,name text not null,active boolean not null default true,unique(user_id,drive_id),unique(id,user_id));
create table public.folders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,drive_id text not null,parent_drive_id text,name text not null,module_id uuid,category text not null default 'Autre',active boolean not null default true,unique(user_id,drive_id),foreign key(module_id,user_id) references modules(id,user_id));
create table public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,drive_id text not null,parent_drive_id text,name text not null,mime_type text not null,module_id uuid,category text not null default 'Autre',created_at timestamptz not null,modified_at timestamptz not null,version text not null,source_url text not null,size_bytes bigint,status text not null default 'pending' check(status in ('pending','queued','processing','ready','failed','unsupported')),processing_error text,active boolean not null default true,last_synced_at timestamptz not null default now(),unique(user_id,drive_id),unique(id,user_id),foreign key(module_id,user_id) references modules(id,user_id));
create table public.document_chunks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,document_id uuid not null,version text not null,ordinal integer not null,content text not null,section text,page integer,content_hash text not null,embedding vector(768),unique(document_id,version,ordinal),foreign key(document_id,user_id) references documents(id,user_id) on delete cascade);
create index chunks_embedding_idx on document_chunks using hnsw(embedding vector_cosine_ops);
create index chunks_keyword_idx on document_chunks using gin(to_tsvector('simple',content));
create table public.document_processing_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,document_id uuid not null,version text not null,status text not null default 'pending' check(status in ('pending','processing','done','failed')),attempts integer not null default 0,error text,created_at timestamptz not null default now(),locked_at timestamptz,unique(document_id,version),foreign key(document_id,user_id) references documents(id,user_id) on delete cascade);
create table public.drive_connections(user_id uuid primary key references auth.users on delete cascade,encrypted_tokens text not null,root_id text not null,page_token text,updated_at timestamptz not null default now());
create table public.sync_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,status text not null default 'running' check(status in ('running','completed','failed')),started_at timestamptz not null default now(),finished_at timestamptz,added integer not null default 0,updated integer not null default 0,removed integer not null default 0,error text);
create unique index one_sync_per_user on sync_runs(user_id) where status='running';
create table public.quizzes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null,module_id uuid,kind text not null default 'quiz' check(kind in ('quiz','exam')),duration_minutes integer check(duration_minutes between 1 and 300),cache_key text not null,created_at timestamptz not null default now(),unique(id,user_id),foreign key(module_id,user_id) references modules(id,user_id));
create table public.questions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,quiz_id uuid not null,ordinal integer not null,payload jsonb not null,unique(quiz_id,ordinal),foreign key(quiz_id,user_id) references quizzes(id,user_id) on delete cascade);
create table public.quiz_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,quiz_id uuid not null,answers jsonb not null default '{}',score integer not null check(score>=0),total integer not null check(total>0 and score<=total),completed_at timestamptz not null default now(),unique(id,user_id),foreign key(quiz_id,user_id) references quizzes(id,user_id));
create table public.quiz_answers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,attempt_id uuid not null,question_id uuid not null,answer jsonb,correct boolean not null,foreign key(attempt_id,user_id) references quiz_attempts(id,user_id) on delete cascade);
create table public.exam_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,quiz_id uuid not null,answers jsonb not null default '{}',started_at timestamptz not null default now(),submitted_at timestamptz,score integer,total integer,unique(id,user_id),foreign key(quiz_id,user_id) references quizzes(id,user_id));
create table public.exercises(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,document_id uuid not null,title text not null,statement text not null,hint text,solution text,source jsonb not null,language text not null default 'python',unique(id,user_id),foreign key(document_id,user_id) references documents(id,user_id));
create table public.exercise_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,exercise_id uuid not null,answer text not null,completed boolean not null default false,created_at timestamptz not null default now(),foreign key(exercise_id,user_id) references exercises(id,user_id));
create table public.flashcards(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,document_id uuid not null,question text not null,answer text not null,explanation text not null default '',source jsonb not null,difficulty text not null default 'Moyen',repetitions integer not null default 0,interval_days integer not null default 0,ease numeric not null default 2.5,due_at timestamptz not null default now(),unique(id,user_id),foreign key(document_id,user_id) references documents(id,user_id));
create table public.flashcard_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,flashcard_id uuid not null,rating integer not null check(rating between 0 and 5),reviewed_at timestamptz not null default now(),foreign key(flashcard_id,user_id) references flashcards(id,user_id));
create table public.study_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,module_id uuid,duration_seconds integer not null check(duration_seconds>=0),created_at timestamptz not null default now(),foreign key(module_id,user_id) references modules(id,user_id));
create table public.study_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null,exam_date date,created_at timestamptz not null default now(),unique(id,user_id));
create table public.study_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,module_id uuid,title text not null,scheduled_date date not null,duration_minutes integer not null default 30 check(duration_minutes between 5 and 480),completed boolean not null default false,exam_date date,foreign key(module_id,user_id) references modules(id,user_id));
create table public.learning_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,module_id uuid not null,topic text not null,correct integer not null default 0,total integer not null default 0,updated_at timestamptz not null default now(),unique(user_id,module_id,topic),foreign key(module_id,user_id) references modules(id,user_id));
create table public.ai_usage_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,operation text not null,model text not null,input_tokens integer not null default 0,output_tokens integer not null default 0,created_at timestamptz not null default now());
create index usage_user_date on ai_usage_logs(user_id,created_at);
create table public.ai_cache(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,cache_key text not null,payload jsonb not null,created_at timestamptz not null default now(),unique(user_id,cache_key));
create table public.api_rate_limits(user_id uuid not null references auth.users on delete cascade,bucket text not null,window_start timestamptz not null default now(),requests integer not null default 1,primary key(user_id,bucket));
-- User data uses ownership policies. Server-managed learning results are read-only to browser clients.
do $$ declare t text; begin foreach t in array array['modules','folders','documents','document_chunks','document_processing_jobs','sync_runs','quizzes','questions','quiz_attempts','quiz_answers','exam_attempts','exercises','exercise_attempts','flashcards','flashcard_reviews','study_sessions','study_plans','study_tasks','learning_progress','ai_usage_logs','ai_cache'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy owner_read on public.%I for select to authenticated using (auth.uid()=user_id)',t); execute format('create index on public.%I(user_id)',t); end loop; end $$;
alter table public.profiles enable row level security;
create policy own_profile on profiles for select to authenticated using(auth.uid()=id);
create policy update_profile on profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
alter table public.drive_connections enable row level security;
-- No token access for authenticated clients, including the account owner.
revoke all on drive_connections from anon,authenticated;
grant select(user_id,root_id,updated_at) on drive_connections to authenticated;
create policy connection_status on drive_connections for select to authenticated using(auth.uid()=user_id);
alter table public.api_rate_limits enable row level security;
create function public.reserve_ai_call(p_user uuid,p_limit integer,p_operation text,p_model text) returns uuid language plpgsql security definer set search_path=public as $$ declare result uuid; begin perform pg_advisory_xact_lock(hashtextextended(p_user::text,11)); if (select count(*) from ai_usage_logs where user_id=p_user and created_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC')>=p_limit then raise exception 'DAILY_AI_LIMIT'; end if; insert into ai_usage_logs(user_id,operation,model) values(p_user,p_operation,p_model) returning id into result; return result; end $$;
create function public.check_rate_limit(p_user uuid,p_bucket text,p_limit integer,p_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ declare r api_rate_limits; begin insert into api_rate_limits(user_id,bucket) values(p_user,p_bucket) on conflict(user_id,bucket) do update set requests=case when api_rate_limits.window_start<now()-make_interval(secs=>p_seconds) then 1 else api_rate_limits.requests+1 end,window_start=case when api_rate_limits.window_start<now()-make_interval(secs=>p_seconds) then now() else api_rate_limits.window_start end returning * into r; return r.requests<=p_limit; end $$;
create function public.match_chunks(p_user uuid,p_embedding vector(768),p_query text,p_documents uuid[] default null,p_module uuid default null) returns table(id uuid,document_id uuid,content text,section text,page integer,document_name text,source_url text,similarity double precision) language sql stable security definer set search_path=public as $$ select c.id,c.document_id,c.content,c.section,c.page,d.name,d.source_url,1-(c.embedding<=>p_embedding) from document_chunks c join documents d on c.document_id=d.id where c.user_id=p_user and d.active and d.status='ready' and c.version=d.version and (p_documents is null or d.id=any(p_documents)) and (p_module is null or d.module_id=p_module) order by (1-(c.embedding<=>p_embedding)) + case when to_tsvector('simple',c.content)@@plainto_tsquery('simple',p_query) then 0.15 else 0 end desc limit 12 $$;
create function public.claim_document_job() returns setof document_processing_jobs language sql security definer set search_path=public as $$ update document_processing_jobs set status='processing',locked_at=now(),attempts=attempts+1 where id=(select id from document_processing_jobs where (status='pending' or (status='processing' and locked_at<now()-interval '10 minutes')) and attempts<3 order by created_at for update skip locked limit 1) returning * $$;
create function public.finish_document(p_job uuid,p_user uuid,p_document uuid,p_version text,p_chunks jsonb) returns boolean language plpgsql security definer set search_path=public as $$ begin perform 1 from documents where id=p_document and user_id=p_user and version=p_version and active for update; if not found then update document_processing_jobs set status='done',error='Version superseded' where id=p_job; return false; end if; delete from document_chunks where document_id=p_document; insert into document_chunks(user_id,document_id,version,ordinal,content,section,page,content_hash,embedding) select p_user,p_document,p_version,(x->>'ordinal')::integer,x->>'content',x->>'section',(x->>'page')::integer,x->>'content_hash',(x->>'embedding')::vector from jsonb_array_elements(p_chunks) x; update documents set status='ready',processing_error=null where id=p_document; update document_processing_jobs set status='done',error=null where id=p_job and user_id=p_user; return true; end $$;
create function public.review_card(p_user uuid,p_card uuid,p_rating integer) returns void language plpgsql security definer set search_path=public as $$ declare c flashcards; n integer; e numeric; days integer; begin if p_rating not between 0 and 5 then raise exception 'Invalid rating'; end if; select * into strict c from flashcards where id=p_card and user_id=p_user for update; n=case when p_rating<3 then 0 else c.repetitions+1 end; e=greatest(1.3,c.ease+0.1-(5-p_rating)*(0.08+(5-p_rating)*0.02)); days=case when p_rating<3 then 1 when n=1 then 1 when n=2 then 6 else round(c.interval_days*c.ease) end; update flashcards set repetitions=n,ease=e,interval_days=days,due_at=now()+make_interval(days=>days) where id=p_card; insert into flashcard_reviews(user_id,flashcard_id,rating) values(p_user,p_card,p_rating); end $$;
-- Explicit service-only RPCs: no user can impersonate another user through p_user.
revoke all on function reserve_ai_call,check_rate_limit,match_chunks,claim_document_job,finish_document,review_card from public,anon,authenticated;
grant execute on function reserve_ai_call,check_rate_limit,match_chunks,claim_document_job,finish_document,review_card to service_role;
commit;